public class Cipher {
    public static void main(String[] args) {
 
        String str = "The quick brown fox Jumped over the lazy Dog";
 
        System.out.println( Cipher.encode( str, 12 ));
        System.out.println( Cipher.decode( Cipher.encode( str, 12), 12 ));
