            double r = a + b * pow(theta, 1 / c);
            double x = r * cos(theta);
            double y = r * sin(theta);
            plot(g, (int) (center + x), (int) (center - y));
        }
    }
 
    void plot(Graphics2D g, int x, int y) {
        g.drawOval(x, y, 1, 1);
    }
 
