    static final int    MAX_NUMBER = 250;
 
    public static void main( String[] args )
    {
        boolean found = false;
        long[]  fifth = new long[ MAX_NUMBER ];
 
        for( int i = 1; i <= MAX_NUMBER; i ++ )
