import org.apache.commons.math3.fraction.BigFraction;
 
public class BernoulliNumbers {
 
    public static void main(String[] args) {
        for (int n = 0; n <= 60; n++) {
            BigFraction b = bernouilli(n);
            if (!b.equals(BigFraction.ZERO))
