        double[] points = new double[a + 1];
 
        Path2D p = new Path2D.Double();
        p.moveTo(a, 0);
 
        // calculate first quadrant
        for (int x = a; x >= 0; x--) {
            points[x] = pow(pow(a, exp) - pow(x, exp), 1 / exp); // solve for y
            p.lineTo(x, -points[x]);
        }
 
