        for (int x = 0; x <= a; x++)
            p.lineTo(x, points[x]);
 
        for (int x = a; x >= 0; x--)
            p.lineTo(-x, points[x]);
 
        for (int x = 0; x <= a; x++)
            p.lineTo(-x, -points[x]);
 
        g.translate(getWidth() / 2, getHeight() / 2);
        g.setStroke(new BasicStroke(2));
 
        g.setColor(new Color(0x25B0C4DE, true));
        g.fill(p);
 
        g.setColor(new Color(0xB0C4DE)); // LightSteelBlue
        g.draw(p);
    }
 
