import java.util.HashMap;
import java.util.Map;
 
public class HofQ {
	private static Map<Integer, Integer> q = new HashMap<Integer, Integer>(){{
		put(1, 1);
		put(2, 1);
	}};
 
	private static int[] nUses = new int[100001];//not part of the task
 
	public static int Q(int n){
