    for (var c = 0; c < numOfCols(board); c++)
        header += c + ' ';
 
    // Then the side-header + board
    var sideboard = [];
    for (var r = 0; r < numOfRows(board); r++) {
        sideboard.push(r + ' [' + board[r].join(' ') + ']');
    }
 
