from sympy import divisors
 
def chowla(n):
    return 0 if n < 2 else sum(divisors(n, generator=True)) - 1 -n
 
def is_prime(n):
    return chowla(n) == 0
 
def primes_to(n):
    return sum(chowla(i) == 0 for i in range(2, n))
 
def perfect_between(n, m):
