public class ArrayCallback7 {
 
    interface IntConsumer {
        void run(int x);
    }
 
    interface IntToInt {
        int run(int x);
    }
 
    static void forEach(int[] arr, IntConsumer consumer) {
        for (int i : arr) {
            consumer.run(i);
        }
    }
 
    static void update(int[] arr, IntToInt mapper) {
        for (int i = 0; i < arr.length; i++) {
            arr[i] = mapper.run(arr[i]);
        }
    }
 
